-- ============================================================================
-- PulseCast Internet Radio Streaming System
-- Supabase PostgreSQL Database Schema (backend/sql/supabase_schema.sql)
-- Target: Supabase PostgreSQL (Postgres 15+)
--
-- Safety & Idempotency:
-- - Safely rerunnable without dropping tables or deleting existing data.
-- - Uses explicit 'public' schema throughout.
-- - Uses BIGINT GENERATED BY DEFAULT AS IDENTITY for primary keys and matching BIGINT foreign keys.
-- - Preserves existing numerical IDs during migration.
-- - Row Level Security (RLS) enabled on all tables.
-- - Public SELECT granted only to active stations, tracks, and published schedules.
-- - Users and favourites strictly inaccessible to anonymous clients.
-- - No anonymous INSERT, UPDATE, DELETE permissions.
-- ============================================================================

-- Ensure public schema exists
CREATE SCHEMA IF NOT EXISTS public;

-- ----------------------------------------------------------------------------
-- 1. Table: public.users
-- Roles: 'listener', 'admin'
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.users (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(100) NOT NULL,
  email VARCHAR(191) NOT NULL,
  password_hash VARCHAR(255) NOT NULL,
  role VARCHAR(20) NOT NULL DEFAULT 'listener',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT uq_users_email UNIQUE (email),
  CONSTRAINT chk_users_role CHECK (role IN ('listener', 'admin'))
);

CREATE INDEX IF NOT EXISTS idx_users_email ON public.users (email);
CREATE INDEX IF NOT EXISTS idx_users_role ON public.users (role);

-- ----------------------------------------------------------------------------
-- 2. Table: public.stations
-- Radio station catalogue with stream endpoints and active state
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.stations (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  name VARCHAR(150) NOT NULL,
  description TEXT,
  genre VARCHAR(80),
  stream_url VARCHAR(500) NOT NULL,
  artwork_url VARCHAR(500),
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT NOW()
);

CREATE INDEX IF NOT EXISTS idx_stations_active ON public.stations (is_active);
CREATE INDEX IF NOT EXISTS idx_stations_genre ON public.stations (genre);

-- ----------------------------------------------------------------------------
-- Trigger Function: Auto-update updated_at on public.stations
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.update_updated_at_column()
RETURNS TRIGGER AS $$
BEGIN
  NEW.updated_at = NOW();
  RETURN NEW;
END;
$$ LANGUAGE plpgsql;

DROP TRIGGER IF EXISTS trigger_stations_updated_at ON public.stations;
CREATE TRIGGER trigger_stations_updated_at
  BEFORE UPDATE ON public.stations
  FOR EACH ROW
  EXECUTE FUNCTION public.update_updated_at_column();

-- ----------------------------------------------------------------------------
-- 3. Table: public.upcoming_tracks
-- Stores songs, audio segments or stream details to be played next
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.upcoming_tracks (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  station_id BIGINT NOT NULL,
  title VARCHAR(200) NOT NULL,
  artist VARCHAR(200) NOT NULL,
  album VARCHAR(200),
  duration VARCHAR(20) DEFAULT '03:45',
  stream_url VARCHAR(500),
  play_order INT NOT NULL DEFAULT 1,
  status VARCHAR(20) NOT NULL DEFAULT 'queued',
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_tracks_station FOREIGN KEY (station_id) REFERENCES public.stations(id) ON DELETE CASCADE,
  CONSTRAINT chk_tracks_status CHECK (status IN ('playing', 'queued', 'played'))
);

CREATE INDEX IF NOT EXISTS idx_tracks_station ON public.upcoming_tracks (station_id, play_order);
CREATE INDEX IF NOT EXISTS idx_tracks_status ON public.upcoming_tracks (status);

-- ----------------------------------------------------------------------------
-- 4. Table: public.program_schedules
-- Station program schedules with start and end times
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.program_schedules (
  id BIGINT GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
  station_id BIGINT NOT NULL,
  title VARCHAR(150) NOT NULL,
  description TEXT,
  start_time VARCHAR(10) NOT NULL, -- Format: "HH:MM" (e.g. "09:00")
  end_time VARCHAR(10) NOT NULL,   -- Format: "HH:MM" (e.g. "12:00")
  is_published BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT fk_schedules_station FOREIGN KEY (station_id) REFERENCES public.stations(id) ON DELETE CASCADE,
  CONSTRAINT chk_schedules_time CHECK (start_time <> end_time)
);

CREATE INDEX IF NOT EXISTS idx_schedules_station_time ON public.program_schedules (station_id, start_time);
CREATE INDEX IF NOT EXISTS idx_schedules_published ON public.program_schedules (is_published);

-- ----------------------------------------------------------------------------
-- 5. Table: public.favourites
-- Composite join table between users and stations
-- ----------------------------------------------------------------------------
CREATE TABLE IF NOT EXISTS public.favourites (
  user_id BIGINT NOT NULL,
  station_id BIGINT NOT NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT NOW(),
  CONSTRAINT pk_favourites PRIMARY KEY (user_id, station_id),
  CONSTRAINT fk_favourites_user FOREIGN KEY (user_id) REFERENCES public.users(id) ON DELETE CASCADE,
  CONSTRAINT fk_favourites_station FOREIGN KEY (station_id) REFERENCES public.stations(id) ON DELETE CASCADE
);

CREATE INDEX IF NOT EXISTS idx_favourites_user ON public.favourites (user_id);
CREATE INDEX IF NOT EXISTS idx_favourites_station ON public.favourites (station_id);

-- ----------------------------------------------------------------------------
-- Helper Function: Reset all identity sequences after data migration
-- ----------------------------------------------------------------------------
CREATE OR REPLACE FUNCTION public.reset_all_sequences()
RETURNS void
LANGUAGE plpgsql
SECURITY DEFINER
SET search_path = pg_catalog, public
AS $$
BEGIN
  PERFORM setval(
    pg_get_serial_sequence('public.users', 'id'),
    COALESCE((SELECT MAX(id) FROM public.users), 1),
    EXISTS (SELECT 1 FROM public.users)
  );

  PERFORM setval(
    pg_get_serial_sequence('public.stations', 'id'),
    COALESCE((SELECT MAX(id) FROM public.stations), 1),
    EXISTS (SELECT 1 FROM public.stations)
  );

  PERFORM setval(
    pg_get_serial_sequence('public.upcoming_tracks', 'id'),
    COALESCE((SELECT MAX(id) FROM public.upcoming_tracks), 1),
    EXISTS (SELECT 1 FROM public.upcoming_tracks)
  );

  PERFORM setval(
    pg_get_serial_sequence('public.program_schedules', 'id'),
    COALESCE((SELECT MAX(id) FROM public.program_schedules), 1),
    EXISTS (SELECT 1 FROM public.program_schedules)
  );
END;
$$;

REVOKE ALL ON FUNCTION public.reset_all_sequences()
FROM PUBLIC, anon, authenticated;

GRANT EXECUTE ON FUNCTION public.reset_all_sequences()
TO service_role;

-- ----------------------------------------------------------------------------
-- 6. Row Level Security (RLS) Configuration
-- Keeps RLS enabled across all five tables.
-- Backend service_role key bypasses RLS safely for administrative and user flows.
-- ----------------------------------------------------------------------------
ALTER TABLE public.users ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.stations ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.upcoming_tracks ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.program_schedules ENABLE ROW LEVEL SECURITY;
ALTER TABLE public.favourites ENABLE ROW LEVEL SECURITY;

-- Stations: Allow public (anon + authenticated) to view active stations
DROP POLICY IF EXISTS "Public can view active stations" ON public.stations;
CREATE POLICY "Public can view active stations"
  ON public.stations
  FOR SELECT
  TO anon, authenticated
  USING (is_active = TRUE);

-- Upcoming tracks: Allow public (anon + authenticated) to view track queues
DROP POLICY IF EXISTS "Public can view tracks" ON public.upcoming_tracks;
CREATE POLICY "Public can view tracks"
  ON public.upcoming_tracks
  FOR SELECT
  TO anon, authenticated
  USING (TRUE);

-- Program schedules: Allow public (anon + authenticated) to view published schedules
DROP POLICY IF EXISTS "Public can view published schedules" ON public.program_schedules;
CREATE POLICY "Public can view published schedules"
  ON public.program_schedules
  FOR SELECT
  TO anon, authenticated
  USING (is_published = TRUE);

-- Users and Favourites: NO POLICIES for anon.
-- Any direct request from anonymous clients will return empty / access denied.

-- ----------------------------------------------------------------------------
-- 7. PostgreSQL Privileges & Access Controls
-- Strictly prevents anonymous mutations (INSERT, UPDATE, DELETE).
-- ----------------------------------------------------------------------------
-- Schema usage
GRANT USAGE ON SCHEMA public TO anon, authenticated, service_role;

-- Revoke all modifying privileges on all tables from anon
REVOKE ALL ON TABLE public.users FROM anon;
REVOKE ALL ON TABLE public.stations FROM anon;
REVOKE ALL ON TABLE public.upcoming_tracks FROM anon;
REVOKE ALL ON TABLE public.program_schedules FROM anon;
REVOKE ALL ON TABLE public.favourites FROM anon;

-- Revoke user and favourite table access from anon completely
REVOKE SELECT ON TABLE public.users FROM anon;
REVOKE SELECT ON TABLE public.favourites FROM anon;

-- Grant SELECT only on public catalogue tables to anon and authenticated
GRANT SELECT ON TABLE public.stations TO anon, authenticated;
GRANT SELECT ON TABLE public.upcoming_tracks TO anon, authenticated;
GRANT SELECT ON TABLE public.program_schedules TO anon, authenticated;

-- Service role retains full administrative privileges for the Node.js backend
GRANT ALL ON ALL TABLES IN SCHEMA public TO service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO service_role;
GRANT ALL ON ALL ROUTINES IN SCHEMA public TO service_role;
